20	   Dải nổi cũ chia đoạn bằng drCutAlongX: dải giữa Cầu sông Hàn trên bờ (song-han/fixedSpans.ts), Trần Thị Lý trên bờ (tran-thi-ly/deck.ts),
21	   dải giữa cỏ và vỉa hè gạch hầm (han-tunnel/outdoor.ts hrBuildSurface), dải giữa Thuận Phước trên bờ (thuan-phuoc/deck.ts). */
22	import * as THREE from 'three';
23	import { CONFIG } from '../config';
24	import { drBuildPads } from '../explore/drive/roadData';
25	import type { DrPad } from '../explore/drive/net';
26	import { SH } from '../bridges/song-han/profile';
27	import { TTL } from '../bridges/tran-thi-ly/profile';
