31	export interface DrRect { x0: number; x1: number; z0: number; z1: number }
32	interface DrPiece extends DrRect { y: number; full: boolean; alongX: boolean }   // mảnh mặt đường cần dựng
33	
34	const R = CONFIG.drive.roads, ROAD = CONFIG.roadY, LAND = CONFIG.landY;
35	const EPS = 1e-6, MIN = 1e-3;                                       // m — chồng nhau / mảnh bỏ qua khi mỏng hơn
36	const LIFT = 0.02;                                                  // m — mặt đường mới cao hơn mặt đất đường, như ROADS2 ven sông (streets.ts y − 0,01)
37	const PLAIN_V = 0.3;                                                // v texture road2 ở vùng nhựa trơn (vạch mép 0,06 / 0,94, vạch giữa 0,5)
38	const MED_H = 0.3;                                                  // m — dải giữa đường mới cao như streets.ts
39	const LIN = R.median / 2, LOUT = LIN + R.half;                      // 1,5 / 10,5
40	const AX0 = R.axisX0, AX1 = R.axisX1;
41	const RIVER = { W: [-2600, 2600], E: [-2300, 2600] };               // m — z hai đường ven sông trong streets.ts:25
42	const SITE = { W: -3250 + 40, E: -3700 + 40 };                      // m — đầu Bắc mặt đường nối dài trong site.ts:16,32
43	
44	/* hai dải đối xứng quanh tim c theo trục ngang (along x) hoặc dọc (along z), mép trong a, mép ngoài b */
45	const bandX = (x0: number, x1: number, c: number, a: number, b: number): DrRect[] => [{ x0, x1, z0: c - b, z1: c - a }, { x0, x1, z0: c + a, z1: c + b }];
46	const bandZ = (c: number, a: number, b: number, z0: number, z1: number): DrRect[] => [{ x0: c - b, x1: c - a, z0, z1 }, { x0: c + a, x1: c + b, z0, z1 }];
