48	/* ===== Mặt đường đã có (bằng mặt đất, phần cầu / hầm không cần vì ô 'bridge' / 'tunnel' không dựng) ===== */
49	function drOld(): DrRect[] {
50	  const out: DrRect[] = [];
51	  const DR_X = CONFIG.length / 2, DR_IN = CONFIG.median / 2, DR_OUT = DR_IN + CONFIG.lanesPerDir * CONFIG.laneWidth + CONFIG.shoulder;
52	  for (const [a, b] of [[AX0, -DR_X], [DR_X, AX1]]) out.push(...bandX(a, b, 0, DR_IN, DR_OUT));
53	  for (const [a, b] of [[AX0, -SH.fixedStart], [SH.fixedStart, AX1]]) out.push(...bandX(a, b, SH.z, SH.median / 2, SH.median / 2 + SH.laneWidth));
54	  out.push(...bandX(AX0, AX1, TTL.z, TTL.median / 2, TTL.median / 2 + TTL.lanesPerDir * TTL.laneWidth));
55	  const hrW = HR.shoulder * 2 + HR.laneWidth * HR.lanesPerDir;
56	  for (const [a, b] of [[AX0, -HR.coverHalf], [HR.coverHalf, AX1]]) out.push(...bandX(a, b, HR.z, HR.tubeCenter - hrW / 2, HR.tubeCenter + hrW / 2));
57	  out.push(...bandX(R.tpX0, AX1, TP.z, TP.median / 2, TP.median / 2 + 2 * TP.laneWidth));
58	  out.push(...bandZ(-R.riverX, LIN, LOUT, SITE.W, RIVER.W[1]), ...bandZ(R.riverX, LIN, LOUT, SITE.E, RIVER.E[1]));
59	  return out;
60	}
61	/* ===== Trừ hình chữ nhật: alongX = cắt các lát theo x trước (giữ đủ bề ngang z cho ô chạy dọc X) ===== */
62	function drSub(a: DrRect, b: DrRect, alongX: boolean): DrRect[] {
63	  const ix0 = Math.max(a.x0, b.x0), ix1 = Math.min(a.x1, b.x1), iz0 = Math.max(a.z0, b.z0), iz1 = Math.min(a.z1, b.z1);
64	  if (ix1 - ix0 <= EPS || iz1 - iz0 <= EPS) return [a];
65	  const out: DrRect[] = [];
66	  if (alongX) {
67	    out.push({ x0: a.x0, x1: ix0, z0: a.z0, z1: a.z1 }, { x0: ix1, x1: a.x1, z0: a.z0, z1: a.z1 });
68	    out.push({ x0: ix0, x1: ix1, z0: a.z0, z1: iz0 }, { x0: ix0, x1: ix1, z0: iz1, z1: a.z1 });
69	  } else {
70	    out.push({ x0: a.x0, x1: a.x1, z0: a.z0, z1: iz0 }, { x0: a.x0, x1: a.x1, z0: iz1, z1: a.z1 });
71	    out.push({ x0: a.x0, x1: ix0, z0: iz0, z1: iz1 }, { x0: ix1, x1: a.x1, z0: iz0, z1: iz1 });
72	  }
73	  return out.filter((r) => r.x1 - r.x0 > MIN && r.z1 - r.z0 > MIN);
74	}
75	const drSubAll = (a: DrRect, bs: DrRect[], alongX: boolean) => bs.reduce((acc, b) => acc.flatMap((r) => drSub(r, b, alongX)), [a]);
76	const drOverlap = (a: DrRect, b: DrRect) => Math.min(a.x1, b.x1) - Math.max(a.x0, b.x0) > EPS && Math.min(a.z1, b.z1) - Math.max(a.z0, b.z0) > EPS;
77	
78	/* ===== Mảnh mới (tính một lần: dữ liệu thuần, không ngẫu nhiên) ===== */
79	let cache: { pieces: DrPiece[]; medians: DrRect[]; open: DrPad[] } | null = null;
80	function drPlan() {
81	  if (cache) return cache;
82	  const open = drBuildPads().filter((p) => p.kind === 'road' || p.kind === 'slip' || p.kind === 'junction');
83	  const old = drOld();
84	  /* mặt đường nối dài trong site.ts thấp hơn roadY 0,08 m: mảnh lấp chỗ dải giữa của nó dùng cùng cao độ */
85	  const yOf = (r: DrRect) => {
86	    const cx = (r.x0 + r.x1) / 2, cz = (r.z0 + r.z1) / 2;
87	    return Math.abs(Math.abs(cx) - R.riverX) <= LOUT && cz < (cx < 0 ? RIVER.W[0] : RIVER.E[0]) ? LAND + LIFT : ROAD + LIFT;
88	  };
89	  const pieces: DrPiece[] = [], medians: DrRect[] = [];
90	  for (const p of open) {
91	    const alongX = p.x1 - p.x0 >= p.z1 - p.z0, lane = p.kind !== 'junction';
92	    for (const r of drSubAll(p, old, alongX)) {
93	      const full = lane && (alongX ? Math.abs(r.z0 - p.z0) < MIN && Math.abs(r.z1 - p.z1) < MIN : Math.abs(r.x0 - p.x0) < MIN && Math.abs(r.x1 - p.x1) < MIN);
94	      pieces.push({ ...r, y: yOf(r), full, alongX });
95	    }
96	    /* dải giữa đường mới: giữa cặp ô hai chiều (.W/.E hoặc .N/.S) không chồng mặt đường cũ nào */
97	    const m = /^(.*)\.(W|N)$/.exec(p.id);
98	    if (p.kind === 'road' && m && !old.some((o) => drOverlap(o, p))) {
99	      const q = open.find((o) => o.id === `${m[1]}.${m[2] === 'W' ? 'E' : 'S'}`);
100	      if (q) medians.push(m[2] === 'W' ? { x0: p.x1, x1: q.x0, z0: p.z0, z1: p.z1 } : { x0: p.x0, x1: p.x1, z0: p.z1, z1: q.z0 });
101	    }
102	  }
103	  cache = { pieces, medians, open };
104	  return cache;
105	}
