122	/* Hình học đường mới: mặt đường (đẩy vào ROADS2) và dải giữa đường mới (đẩy vào MEDIANS). Mỗi lần gọi trả hình học mới */
123	export function drRoadGeos(): { roads2: THREE.BufferGeometry[]; medians: THREE.BufferGeometry[] } {
124	  const P = drPlan();
125	  const roads2 = P.pieces.map(drQuad);
126	  const medians = P.medians.map((r) => new THREE.BoxGeometry(r.x1 - r.x0, MED_H, r.z1 - r.z0).translate((r.x0 + r.x1) / 2, ROAD + MED_H / 2, (r.z0 + r.z1) / 2));
127	  return { roads2, medians };
128	}
129	/* Mảnh mặt đường mới, tọa độ thế giới: vùng phải dọn nhà / cây / đèn */
130	export function drNewRects(): DrRect[] {
131	  return drPlan().pieces.map((r) => ({ x0: r.x0, x1: r.x1, z0: r.z0, z1: r.z1 }));
132	}
133	/* Điểm (x, z) thế giới có nằm trên mặt đường mới (nới lề margin) không */
134	export function drOnNewRoad(x: number, z: number, margin: number): boolean {
135	  return drPlan().pieces.some((r) => x > r.x0 - margin && x < r.x1 + margin && z > r.z0 - margin && z < r.z1 + margin);
136	}
137	/* Dải giữa / vỉa hè cũ (streets.ts, site.ts) trừ đi mọi ô road / slip / junction: phần còn lại, tọa độ thế giới */
138	export function drCutRects(r: DrRect): DrRect[] {
139	  const alongX = r.x1 - r.x0 >= r.z1 - r.z0;
140	  return drSubAll(r, drPlan().open, alongX);
141	}
142	/* Như drCutRects nhưng trả hộp y0..y1 (BoxGeometry như streets.ts); rect và hình học theo tọa độ cục bộ lệch zOff so với thế giới (site.ts: TP.z) */
143	export function drCutBoxes(x0: number, x1: number, z0: number, z1: number, y0: number, y1: number, zOff = 0): THREE.BufferGeometry[] {
144	  return drCutRects({ x0, x1, z0: z0 + zOff, z1: z1 + zOff }).map((r) => new THREE.BoxGeometry(r.x1 - r.x0, y1 - y0, r.z1 - r.z0).translate((r.x0 + r.x1) / 2, (y0 + y1) / 2, (r.z0 + r.z1) / 2 - zOff));
145	}
146	/* Dải nổi cũ chạy dọc X (dải giữa / vỉa hè trên bờ của các trục cầu, hầm), tim zc (thế giới), nửa bề ngang hw, đoạn x0..x1:
147	   bỏ trọn bề ngang mọi khoảng x mà một ô road / slip / junction chồng lên dải; trả các khoảng [a, b] còn lại */
148	export function drCutSpans(x0: number, x1: number, zc: number, hw: number): [number, number][] {
149	  const band: DrRect = { x0, x1, z0: zc - hw, z1: zc + hw };
150	  let spans: [number, number][] = [[x0, x1]];
151	  for (const p of drPlan().open) {
152	    if (!drOverlap(p, band)) continue;
153	    spans = spans.flatMap(([a, b]): [number, number][] => [[a, Math.min(b, p.x0)], [Math.max(a, p.x1), b]]).filter(([a, b]) => b - a > MIN);
154	  }
155	  return spans;
156	}
157	/* Dựng dải nổi theo các khoảng của drCutSpans: mk(len, xc, segs) như bentBox(len, …, xc, …, segs, profile) của công trình;
158	   số đoạn chia của mỗi khúc theo tỉ lệ chiều dài (vẫn bám profile như trước). Hình học gộp vào đúng lưới cũ: không thêm lệnh vẽ */
159	export function drCutAlongX<G extends THREE.BufferGeometry>(x0: number, x1: number, zc: number, hw: number, segs: number, mk: (len: number, xc: number, segs: number) => G): G[] {
160	  return drCutSpans(x0, x1, zc, hw).map(([a, b]) => mk(b - a, (a + b) / 2, Math.max(1, Math.ceil(segs * (b - a) / (x1 - x0)))));
161	}
