216	  },
217	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho HUD / chụp ảnh của task sau */
218	  afterRender(): void { /* chưa có việc */ },
219	  /* Rời chế độ: trả mọi thứ đã đổi (explore.exit tải lại trang ngay sau), kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'car' */
220	  stop(): void {
221	    if (state === null && !watching) return;
222	    state = null; drKeys.clear(); touch?.reset();
223	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
224	    drHudHide(); drSound.stop();
225	    exDrivers.clear(); drCars.clear(); drCars.group.removeFromParent();
226	    driveView.far = 1;
227	    document.body.classList.remove('drive');
228	    if (saved) {
229	      if (!saved.explore) document.body.classList.remove('explore');
230	      camera.fov = saved.fov; onResize();                            // onResize tính lại ma trận chiếu và pScale theo fov cũ
231	      saved = null;
232	    }
233	    if (cam.mode === 'car') { cam.mode = 'orbit'; controls.enabled = true; }
234	  },
235	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
236	  step(dt: number, inp: DrInput): void { if (active()) advance(dt, inp); },
237	  placeAt: drPlaceAt,
238	  stats: drSceneStats,
