1	/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
2	import { multiParams as P } from '../../../src/explore/multi/params';
3	import { exSanitizeName } from '../../../src/explore/multi/protocol';
4	import type { ServerMsg, Flyer, Kind } from '../../../src/explore/multi/protocol';
5	import { exIsBad } from './badwords';
6	
7	export type Out = { to: string | 'all'; msg: ServerMsg };
8	
9	// pos: [slot, x, y, z, yaw, bank (người đi dạo: pose), giờ gửi]; người lái: [slot, x, y, z, yaw, v, st, giờ gửi]; giờ gửi = ts của khách (khách mới) hoặc giờ máy chủ nhận (khách cũ); dirty: có vị trí mới chưa phát
10	interface Slot { id: string; name: string; seen: number; pos: number[] | null; dirty: boolean }
11	interface Conn { stamps: number[] }
12	
13	const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
14	const wrapPi = (a: number) => a - Math.round(a / (2 * Math.PI)) * 2 * Math.PI;   // góc về [−π, π]
15	
16	export class SkyRoom {
17	  private conns = new Map<string, Conn>();
18	  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
19	  private walkSlots: (Slot | null)[] = new Array(P.stroll.slots).fill(null);   // nhóm chỗ đi dạo, tách khỏi nhóm bay
20	  private driveSlots: (Slot | null)[] = new Array(P.drive.slots).fill(null);   // nhóm chỗ lái xe, tách khỏi hai nhóm kia
21	  private lastBroadcast = -Infinity;
22	
23	  private lobby(): Out {
24	    const flyers: Flyer[] = [];
25	    const walkers: Flyer[] = [];
26	    const drivers: Flyer[] = [];
27	    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
28	    this.walkSlots.forEach((s, i) => { if (s) walkers.push({ slot: i, name: s.name }); });
29	    this.driveSlots.forEach((s, i) => { if (s) drivers.push({ slot: i, name: s.name }); });
30	    return { to: 'all', msg: { t: 'lobby', flyers, walkers, drivers } };
31	  }
32	
33	  connect(id: string, now: number): Out[] | null {
34	    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
35	    this.conns.set(id, { stamps: [] });
36	    return [{ to: id, msg: this.lobby().msg }];
37	  }
38	
39	  slotOf(id: string): number { return this.slots.findIndex(s => s !== null && s.id === id); }   // slot bay, -1 nếu không bay
40	
41	  walkSlotOf(id: string): number { return this.walkSlots.findIndex(s => s !== null && s.id === id); }   // slot đi dạo, -1 nếu không đi dạo
42	
43	  driveSlotOf(id: string): number { return this.driveSlots.findIndex(s => s !== null && s.id === id); }   // slot lái xe, -1 nếu không lái
44	
45	  kindOf(id: string): Kind | null { return this.slotOf(id) >= 0 ? 'fly' : this.walkSlotOf(id) >= 0 ? 'walk' : this.driveSlotOf(id) >= 0 ? 'drive' : null; }
