49	  private groupOf(kind: Kind | null): (Slot | null)[] { return kind === 'walk' ? this.walkSlots : kind === 'drive' ? this.driveSlots : this.slots; }
50	
51	  /* Giờ có tin cuối của người giữ slot (để lưu vào attachment); -1 nếu không giữ slot */
52	  seenOf(id: string): number {
53	    const i = this.slotOf(id);
54	    if (i >= 0) return this.slots[i].seen;
55	    const w = this.walkSlotOf(id);
56	    if (w >= 0) return this.walkSlots[w].seen;
57	    const d = this.driveSlotOf(id);
58	    return d < 0 ? -1 : this.driveSlots[d].seen;
59	  }
60	
61	  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
62	     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
63	  restore(list: { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive' }[], now: number): void {
64	    for (const e of list) {
65	      const group = this.groupOf(e.kind === 'walk' || e.kind === 'drive' ? e.kind : 'fly');
66	      if (e.slot < 0 || e.slot >= group.length) continue;
67	      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [] });
68	      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
69	      group[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false };
70	    }
71	  }
72	
73	  message(id: string, raw: string, now: number): Out[] {
74	    const conn = this.conns.get(id);
75	    if (!conn || typeof raw !== 'string' || raw.length > P.maxMsgBytes) return [];
76	    let m: any;
77	    try { m = JSON.parse(raw); } catch { return []; }
78	    if (!m || typeof m !== 'object') return [];
79	    const kind = this.kindOf(id);   // loại theo slot kết nối đang giữ, không theo trường trong gói
80	    const group = this.groupOf(kind);
81	    const slot = kind === null ? -1 : group.findIndex(s => s !== null && s.id === id);
82	    switch (m.t) {
83	      case 'join': return this.onJoin(id, kind !== null, m.name, m.kind === 'walk' || m.kind === 'drive' ? m.kind : 'fly', now);
84	      case 'leave': return this.release(id) ? [this.lobby()] : [];
85	      case 'hb': if (slot < 0) return []; group[slot].seen = now; return this.flush(now);
86	      case 'pos': return slot >= 0 ? this.onPos(conn, group[slot]!, slot, kind, m, now) : [];
