92	  private onJoin(id: string, holding: boolean, rawName: unknown, kind: Kind, now: number): Out[] {
93	    if (holding) return [];
94	    const k = kind === 'fly' ? {} : { kind };
95	    const name = typeof rawName === 'string' ? exSanitizeName(rawName) : null;
96	    if (name === null || exIsBad(name)) return [{ to: id, msg: { t: 'rejected', why: 'name', ...k } }];
97	    const group = this.groupOf(kind);
98	    const free = group.findIndex(s => s === null);
99	    if (free < 0) return [{ to: id, msg: { t: 'rejected', why: 'full', ...k } }];
100	    group[free] = { id, name, seen: now, pos: null, dirty: false };
101	    return [{ to: id, msg: { t: 'joined', slot: free, ...k } }, this.lobby()];
102	  }
103	
104	  private onPos(conn: Conn, s: Slot, slot: number, kind: Kind, m: any, now: number): Out[] {
105	    const { x, y, z, yaw, ts } = m;
106	    const walk = kind === 'walk', drive = kind === 'drive';
107	    const tilt = drive ? m.v : walk ? m.pose : m.bank;   // người lái gửi v + st, người đi dạo gửi pose, người bay gửi bank; trường của loại khác bị bỏ qua
108	    const st = drive ? m.st : 0;
109	    for (const v of [x, y, z, yaw, tilt, st]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
