126	  }
127	
128	  /* Phát gói gộp các slot có vị trí mới (cách lần trước >= broadcastMs). Vị trí bị hãm trong cửa sổ vẫn dirty nên đi ở lần phát sau (pos hoặc hb của bất kỳ ai).
129	     Không phát lại vị trí cũ: khách cũ đóng dấu theo giờ nhận nên mẫu lặp làm dù đứng rồi vọt. Khách mới đặt mẫu theo e[6] */
130	  private flush(now: number): Out[] {
131	    if (now - this.lastBroadcast < P.broadcastMs) return [];
132	    const f: number[][] = [], w: number[][] = [], d: number[][] = [];
133	    for (const t of this.slots) if (t && t.dirty) { f.push(t.pos!); t.dirty = false; }
134	    for (const t of this.walkSlots) if (t && t.dirty) { w.push(t.pos!); t.dirty = false; }
135	    for (const t of this.driveSlots) if (t && t.dirty) { d.push(t.pos!); t.dirty = false; }
136	    if (!f.length && !w.length && !d.length) return [];
137	    this.lastBroadcast = now;
138	    // f luôn có (khách cũ đọc m.f); w / d chỉ có khi có người cử động, khách cũ bỏ qua trường lạ
139	    const msg: { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] } = { t: 'pos', f };
140	    if (w.length) msg.w = w;
141	    if (d.length) msg.d = d;
142	    return [{ to: 'all', msg }];
143	  }
144	
145	  // Trả slot của kết nối; true nếu có slot được trả
146	  private release(id: string): boolean {
147	    const i = this.slotOf(id);
148	    if (i >= 0) { this.slots[i] = null; return true; }
149	    const w = this.walkSlotOf(id);
150	    if (w >= 0) { this.walkSlots[w] = null; return true; }
151	    const d = this.driveSlotOf(id);
152	    if (d < 0) return false;
153	    this.driveSlots[d] = null;
154	    return true;
155	  }
156	
157	  disconnect(id: string): Out[] {
158	    this.conns.delete(id);
159	    return this.release(id) ? [this.lobby()] : [];
160	  }
161	
162	  sweep(now: number): Out[] {
163	    const out: Out[] = [];
164	    for (const group of [this.slots, this.walkSlots, this.driveSlots]) group.forEach((s, i) => {
165	      if (s && now - s.seen > P.slotTimeoutMs) { out.push({ to: s.id, msg: { t: 'released' } }); group[i] = null; }
166	    });
167	    if (out.length) out.push(this.lobby());
168	    return out;
169	  }
170	}
