/* ============================ Lái xe: vật cản thu từ cảnh đã dựng ============================
   Tách khỏi solids.ts vì cần module cảnh (environment/riverfront kéo core/renderer, core/materials vẽ canvas lúc import): test node
   chỉ import solids.ts. Gọi MỘT lần, lần đầu vào chế độ lái (sau mọi bước dọn nhà): chỉ đọc cảnh, không đụng chuỗi rand() hay thứ tự dựng.
   - Nhà đang hiện của khu phố (collectBuildings: level gần của THREE.LOD, bỏ instance scale 0) và nhà quanh Thuận Phước (InstancedMesh
     thường của site.ts, tọa độ cục bộ group cầu): khối hộp thẳng trục từ chân tới mái.
   - Chân đế địa danh và pano ven sông (riverfront footprints): là hình chữ nhật dọn nhà đã nới rộng 2–9 m mỗi phía và không có chiều cao,
     nên phần lấn ô đường bị cắt bỏ (giữ mảnh lớn nhất còn lại), cao CONFIG.drive.solids.footTop.
   - Chỉ giữ vật cách mép ô gần nhất ≤ CONFIG.drive.solids.near (cho thân xe và camera); xa hơn xe không bao giờ tới.
   Nhà lấn ô đường thì vẫn thêm (đúng là có nhà trên đường) và đếm vào drSceneStats.intrude để test trình duyệt / người làm thấy. */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { collectBuildings, type Rect } from '../../environment/riverfront/clearance';
import { getRiverfront } from '../../environment/riverfront';
import { drAddSolids, type DrNet, type DrPad, type DrSolid } from './net';

export const drSceneStats = { buildings: 0, tpHouses: 0, footprints: 0, intrude: 0, skipped: 0 };

const _m = new THREE.Matrix4(), _p = new THREE.Vector3(), _q = new THREE.Quaternion(), _s = new THREE.Vector3();
const drGood = (r: Rect): boolean => [r.x0, r.x1, r.z0, r.z1].every(Number.isFinite) && r.x1 > r.x0 && r.z1 > r.z0;
const drOverlap = (r: Rect, p: DrPad): boolean => r.x1 > p.x0 && r.x0 < p.x1 && r.z1 > p.z0 && r.z0 < p.z1;
/* Khoảng cách mặt bằng nhỏ nhất từ r tới ô gần nhất (0 nếu chồng) */
function drPadGap(pads: DrPad[], r: Rect): number {
  let best = Infinity;
  for (const p of pads) {
    const dx = Math.max(0, p.x0 - r.x1, r.x0 - p.x1), dz = Math.max(0, p.z0 - r.z1, r.z0 - p.z1);
    best = Math.min(best, Math.hypot(dx, dz));
  }
  return best;
}
/* Cắt khỏi r phần chồng lên các ô: mỗi lần chồng giữ mảnh lớn nhất trong bốn mảnh trái / phải / trước / sau; null nếu không còn gì */
function drTrim(pads: DrPad[], r: Rect): Rect | null {
  let cur: Rect = { ...r };
  for (const p of pads) {
    if (!drOverlap(cur, p)) continue;
    const parts: Rect[] = [
      { ...cur, x1: Math.min(cur.x1, p.x0) }, { ...cur, x0: Math.max(cur.x0, p.x1) },
      { ...cur, z1: Math.min(cur.z1, p.z0) }, { ...cur, z0: Math.max(cur.z0, p.z1) }
    ].filter(drGood);
    if (!parts.length) return null;
    cur = parts.reduce((a, b) => ((b.x1 - b.x0) * (b.z1 - b.z0) > (a.x1 - a.x0) * (a.z1 - a.z0) ? b : a));
  }
  return cur;
}

/* Thêm nhà đang hiện + chân đế địa danh gần ô đường vào net; trả số vật cản đã thêm */
export function drCollectRuntime(net: DrNet, tpHouses: THREE.InstancedMesh | null): number {
  const C = CONFIG.drive.solids, LAND = CONFIG.landY, pads = net.pads, out: DrSolid[] = [];
  const st = { buildings: 0, tpHouses: 0, footprints: 0, intrude: 0, skipped: 0 };
  const box = (r: Rect, y0: number, y1: number): boolean => {
    if (!drGood(r) || !Number.isFinite(y0) || !Number.isFinite(y1) || y1 <= y0) { st.skipped++; return false; }
    const gap = drPadGap(pads, r);
    if (gap > C.near) return false;
    if (gap === 0 && pads.some((p) => drOverlap(r, p))) st.intrude++;
    out.push({ kind: 'rect', x0: r.x0, x1: r.x1, z0: r.z0, z1: r.z1, y0, y1 });
    return true;
  };
  for (const b of collectBuildings()) {                             // collectBuildings đã cập nhật matrixWorld của cảnh; nhà khu phố đặt chân ở landY (city.ts)
    if (box({ x0: b.x - b.w / 2, x1: b.x + b.w / 2, z0: b.z - b.d / 2, z1: b.z + b.d / 2 }, LAND, LAND + b.h)) st.buildings++;
  }
  if (tpHouses) {
    tpHouses.updateWorldMatrix(true, false);
    for (let i = 0; i < tpHouses.count; i++) {
      tpHouses.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
      if (_s.x < 1e-6) continue;                                    // nhà đã dọn khỏi đường mới (drClearRoads)
      _p.applyMatrix4(tpHouses.matrixWorld);                         // hộp gốc ở chân (site.ts: BoxGeometry dời lên 0,5)
      if (box({ x0: _p.x - _s.x / 2, x1: _p.x + _s.x / 2, z0: _p.z - _s.z / 2, z1: _p.z + _s.z / 2 }, _p.y, _p.y + _s.y)) st.tpHouses++;
    }
  }
  for (const f of getRiverfront()?.footprints ?? []) {
    if (!drGood(f)) { st.skipped++; continue; }
    const r = drTrim(pads, f);
    if (r && box(r, LAND, LAND + C.footTop)) st.footprints++;
  }
  if (st.skipped) console.warn(`[drive] bỏ ${st.skipped} vật cản hỏng khi thu từ cảnh`);
  if (st.intrude) console.warn(`[drive] ${st.intrude} nhà lấn ô đường`);
  Object.assign(drSceneStats, st);
  drAddSolids(net, out);
  return out.length;
}
/* ============================ Lái xe: HUD (đồng hồ tốc độ, bản đồ nhỏ, gợi ý phím) ============================
   DOM + canvas 2D, không tốn lệnh vẽ 3D. Khung #drHud (index.html): #drSpeed / #drKmh (km/h), #drMap (canvas), #drMapNote (chú thích Hầm), #drHint.
   - Bản đồ nhỏ: Bắc (−Z) ở trên, Đông ở phải, không xoay. Nền (sông, đất, các ô mặt đường, năm công trình) vẽ MỘT lần vào canvas ẩn từ chính
     mạng đường DrNet (không lệch với đường lái được); mỗi lần cập nhật chỉ chép nền + chấm xe, tối đa CONFIG.drive.hud.mapMs một lần (10 lần/giây).
   - Hầm vượt sông Hàn là công trình chưa xây: ô hầm vẽ màu riêng và chú thích #drMapNote ghi "phương án đề xuất" (khóa drMapTunnel).
   - Đồng hồ: ghi DOM chỉ khi số km/h đổi; không tạo chuỗi / mảng mới khi giá trị hiển thị không đổi (D-018).
   - Gợi ý phím tự ẩn sau CONFIG.drive.hud.hintMs (chỉ hiện ở máy có chuột, CSS). Module không đụng DOM lúc import (test đơn vị chạy trong Node). */
import { CONFIG } from '../../config';
import { drBounds, type DrNet } from './net';
import type { DrState } from './motion';

export interface DrMapDot { x: number; z: number; color: string }
type DrRect = { x0: number; x1: number; z0: number; z1: number };

/* Chiếu (x, z) lên ô w × h px, một tỉ lệ cho cả hai trục: góc Tây Bắc (x0, z0) về (0, 0), Bắc (−Z) ở trên, Đông ở phải */
export function drMapProject(b: DrRect, w: number, h: number, x: number, z: number, out: { u: number; v: number }): void {
  const s = Math.min(w / (b.x1 - b.x0), h / (b.z1 - b.z0));
  out.u = (x - b.x0) * s; out.v = (z - b.z0) * s;
}

/* km/h hiển thị của tốc độ v (m/s, có dấu): làm tròn |v| × 3,6 */
export function drKmh(v: number): number { return Math.round(Math.abs(v) * 3.6); }

const H = CONFIG.drive.hud;
const _p = { u: 0, v: 0 };                                          // điểm chiếu tái dùng
let net: DrNet | null = null, bounds: DrRect | null = null;
let el: { root: HTMLElement | null; kmh: HTMLElement | null; map: HTMLCanvasElement | null; hint: HTMLElement | null } | null = null;
let bg: HTMLCanvasElement | null = null, bgNet: DrNet | null = null;   // nền bản đồ nhỏ và mạng đường nó vẽ từ
let ctx: CanvasRenderingContext2D | null = null;
let mw = 0, mh = 0;                                                  // cỡ canvas bản đồ (px)
let lastKmh = -1, lastMap = -1e9, hintTimer = 0;

/* Nền bản đồ nhỏ: đất, sông (|x| < bankX), ô mặt đường theo loại, năm công trình. Vẽ lại khi đổi mạng hoặc cỡ */
function drMapBackdrop(n: DrNet, b: DrRect, w: number, h: number): HTMLCanvasElement {
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const g = c.getContext('2d')!, C = H.colors, p = _p;
  g.fillStyle = C.land; g.fillRect(0, 0, w, h);
  drMapProject(b, w, h, -CONFIG.bankX, b.z0, p); const u0 = p.u;
  drMapProject(b, w, h, CONFIG.bankX, b.z1, p);
  g.fillStyle = C.river; g.fillRect(u0, 0, p.u - u0, h);
  const s = Math.min(w / (b.x1 - b.x0), h / (b.z1 - b.z0));
  /* ô mặt đường: đường thường vẽ trước, cầu rồi hầm đè lên; nét tối thiểu roadMin px */
  for (const kind of ['road', 'junction', 'slip', 'bridge', 'tunnel'] as const) {
    g.fillStyle = kind === 'bridge' ? C.bridge : kind === 'tunnel' ? C.tunnel : C.road;
    for (const q of n.pads) {
      if (q.kind !== kind) continue;
      drMapProject(b, w, h, q.x0, q.z0, p);
      let uu = p.u, vv = p.v, ww = (q.x1 - q.x0) * s, hh = (q.z1 - q.z0) * s;
      if (ww < H.roadMin) { uu -= (H.roadMin - ww) / 2; ww = H.roadMin; }
      if (hh < H.roadMin) { vv -= (H.roadMin - hh) / 2; hh = H.roadMin; }
      g.fillRect(uu, vv, ww, hh);
    }
  }
  /* năm công trình: chấm ở giữa dòng sông (x = 0) tại z của từng công trình; Hầm cùng màu ô hầm (phương án đề xuất, ghi ở chú thích) */
  const marks: [number, string][] = [[CONFIG.songHan.z, C.mark], [0, C.mark], [CONFIG.tranThiLy.z, C.mark], [CONFIG.thuanPhuoc.z, C.mark], [CONFIG.hanTunnel.z, C.tunnel]];
  for (const [z, col] of marks) {
    drMapProject(b, w, h, 0, z, p);
    g.beginPath(); g.arc(p.u, p.v, 2.5, 0, Math.PI * 2); g.fillStyle = col; g.fill();
    g.lineWidth = 1; g.strokeStyle = C.edge; g.stroke();
  }
  g.strokeStyle = C.edge; g.lineWidth = 1; g.strokeRect(0.5, 0.5, w - 1, h - 1);
  return c;
}

function drPlaceDot(x: number, z: number, r: number, col: string): void {
  drMapProject(bounds!, mw, mh, x, z, _p);
  ctx!.beginPath(); ctx!.arc(_p.u, _p.v, r, 0, Math.PI * 2); ctx!.fillStyle = col; ctx!.fill();
}

/* Hiện HUD, dựng bản đồ nền theo mạng đường và cỡ màn hình (điện thoại nhỏ hơn); hẹn giờ ẩn gợi ý phím */
export function drHudShow(n: DrNet): void {
  if (!el) {
    const d = (id: string) => document.getElementById(id);
    el = { root: d('drHud'), kmh: d('drKmh'), map: d('drMap') as HTMLCanvasElement | null, hint: d('drHint') };
  }
  net = n;
  if (!bounds || bgNet !== n) { const b = drBounds(n); bounds = { x0: b.x0, x1: b.x1, z0: b.z0, z1: b.z1 }; }
  const touch = typeof window.matchMedia === 'function' && window.matchMedia('(hover: none)').matches;
  const edge = touch ? H.mapTouch : H.mapDesk, bw = bounds.x1 - bounds.x0, bh = bounds.z1 - bounds.z0;
  const nw = Math.max(1, Math.round(edge * Math.min(1, bw / bh))), nh = Math.max(1, Math.round(edge * Math.min(1, bh / bw)));
  if (el.map) {
    if (nw !== mw || nh !== mh || bgNet !== n) { mw = nw; mh = nh; el.map.width = mw; el.map.height = mh; if (el.root) el.root.style.setProperty('--dr-map-h', mh + 'px'); bg = drMapBackdrop(n, bounds, mw, mh); bgNet = n; }
    ctx = el.map.getContext('2d');
  }
  lastKmh = -1; lastMap = -1e9;
  if (el.hint) el.hint.classList.remove('off');
  window.clearTimeout(hintTimer);
  hintTimer = window.setTimeout(() => { if (el && el.hint) el.hint.classList.add('off'); }, H.hintMs);
}

export function drHudHide(): void {
  window.clearTimeout(hintTimer);
  net = null; ctx = null;
}

/* Mỗi khung: số km/h (ghi DOM khi đổi), bản đồ nhỏ (tối đa mapMs một lần); others: xe người khác (exDrivers.dots) */
export function drHudUpdate(s: Pick<DrState, 'x' | 'z' | 'yaw' | 'v'>, others: DrMapDot[]): void {
  if (!el || !net) return;
  const k = drKmh(s.v);
  if (k !== lastKmh) { lastKmh = k; if (el.kmh) el.kmh.textContent = String(k); }
  const now = performance.now();
  if (!ctx || !bg || !bounds || now - lastMap < H.mapMs) return;
  lastMap = now;
  ctx.drawImage(bg, 0, 0);
  for (let i = 0; i < others.length; i++) drPlaceDot(others[i].x, others[i].z, H.otherR, others[i].color);
  /* xe của mình: mũi tên hướng xe (tiến = (cos yaw, −sin yaw) trên (x, z), cũng là hướng (u, v) vì bản đồ không xoay) */
  drMapProject(bounds, mw, mh, s.x, s.z, _p);
  const fx = Math.cos(s.yaw), fz = -Math.sin(s.yaw), R = H.meR;
  ctx.beginPath();
  ctx.moveTo(_p.u + fx * R * 1.5, _p.v + fz * R * 1.5);
  ctx.lineTo(_p.u - fx * R + fz * R * 0.9, _p.v - fz * R - fx * R * 0.9);
  ctx.lineTo(_p.u - fx * R - fz * R * 0.9, _p.v - fz * R + fx * R * 0.9);
  ctx.closePath(); ctx.fillStyle = H.colors.me; ctx.fill();
  ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(0,0,0,.6)'; ctx.stroke();
}
/* ============================ Lái xe: tiếng mô tơ điện và còi ============================
   Tổng hợp bằng Web Audio, không tệp âm thanh. Dùng chung AudioContext và nút tắt tiếng của trang (audio/index.ts sfxPort):
   - Không tự tạo AudioContext: chỉ nối vào khi người xem đã bấm phát âm thanh (chính sách autoplay); chưa thì im lặng và thử lại mỗi lần update.
   - Nối vào nút hiệu ứng (sfx) → master, nên tắt tiếng chung hay âm lượng chung đều chặn / chỉnh luôn tiếng xe.
   - Mô tơ: hai dao động (tam giác + sin ở quãng tám trên) qua lọc thông thấp, tần số và âm lượng theo |v|. Còi: hai nốt vuông cùng bật / tắt.
   - update chỉ ghi tham số tối đa mỗi CONFIG.drive.sound.updateMs (mỗi lần là một sự kiện tự động hoá, D-018). stop() dừng và ngắt mọi nút. */
import { CONFIG } from '../../config';
import { audio } from '../../audio';

interface DrSnd { ctx: AudioContext; o1: OscillatorNode; o2: OscillatorNode; lp: BiquadFilterNode; g: GainNode; hg: GainNode; h: OscillatorNode[] }
let snd: DrSnd | null = null;
let want = false, hornOn = false, lastAt = -1e9;

/* Dựng chuỗi nút nếu âm thanh trang đã sẵn sàng; trả có dựng được không */
function drSndBuild(): boolean {
  const port = audio.sfxPort();
  if (!port) return false;
  const S = CONFIG.drive.sound, { ctx, out } = port;
  const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = S.lowpass;
  const g = ctx.createGain(); g.gain.value = 0;
  const o1 = ctx.createOscillator(); o1.type = 'triangle'; o1.frequency.value = S.base;
  const o2 = ctx.createOscillator(); o2.type = 'sine'; o2.frequency.value = S.base * 2;
  const mix = ctx.createGain(); mix.gain.value = 0.5;
  o1.connect(lp); o2.connect(mix).connect(lp); lp.connect(g).connect(out);
  const hg = ctx.createGain(); hg.gain.value = hornOn ? S.hornGain : 0;
  const h = S.hornHz.map((f) => { const o = ctx.createOscillator(); o.type = 'square'; o.frequency.value = f; o.connect(hg); o.start(); return o; });
  hg.connect(out);
  o1.start(); o2.start();
  snd = { ctx, o1, o2, lp, g, hg, h };
  return true;
}

export const drSound = {
  /* Vào chế độ lái: bật mô tơ (nếu âm thanh trang đã sẵn sàng; nếu chưa, update thử lại) */
  start(): void { want = true; lastAt = -1e9; if (!snd) drSndBuild(); },
  /* Mỗi khung với tốc độ v (m/s, có dấu): ghi tham số tối đa mỗi updateMs */
  update(v: number): void {
    if (!want) return;
    const now = performance.now();
    if (now - lastAt < CONFIG.drive.sound.updateMs) return;
    lastAt = now;
    if (!snd && !drSndBuild()) return;
    const S = CONFIG.drive.sound, a = Math.abs(v), k = Math.min(1, a / CONFIG.drive.perf.vMax), t = snd!.ctx.currentTime;
    snd!.o1.frequency.setTargetAtTime(S.base + S.perMs * a, t, S.smooth);
    snd!.o2.frequency.setTargetAtTime((S.base + S.perMs * a) * 2, t, S.smooth);
    snd!.g.gain.setTargetAtTime(S.gainIdle + (S.gainMax - S.gainIdle) * k, t, S.smooth);
  },
  /* Còi (giữ phím H): đổi trạng thái mới ghi tham số */
  horn(on: boolean): void {
    if (on === hornOn) return;
    hornOn = on;
    if (snd) snd.hg.gain.setTargetAtTime(on ? CONFIG.drive.sound.hornGain : 0, snd.ctx.currentTime, 0.02);
  },
  /* Rời chế độ: dừng các dao động và ngắt nút */
  stop(): void {
    want = false; hornOn = false;
    if (!snd) return;
    for (const o of [snd.o1, snd.o2, ...snd.h]) { try { o.stop(); } catch { /* đã dừng */ } o.disconnect(); }
    snd.lp.disconnect(); snd.g.disconnect(); snd.hg.disconnect();
    snd = null;
  }
};
/* ============================ Lái xe: điều khiển cảm ứng ============================
   Bốn con trỏ độc lập trên #drHud: cần gạt ngang #drSteer (ngón trái), nút GA #drGas và PHANH #drBrake (ngón phải), vuốt #drLook (vùng trống) xoay camera.
   - Mỗi vùng chỉ theo con trỏ đã chạm vào nó (pointerId riêng + setPointerCapture), nên giữ cần gạt, đạp GA và vuốt camera cùng lúc không lẫn nhau;
     ngón trượt ra ngoài vùng vẫn giữ cho tới khi nhấc.
   - Cần gạt chỉ ngang: lấy thành phần x, bỏ thành phần dọc. Đầu ra theo quy ước của lái xe: ngón sang trái = steer > 0 (rẽ trái).
   - Thả tay, pointercancel, lostpointercapture, blur, ẩn tab, xoay màn hình, đổi cỡ khung nhìn đáng kể: reset() (Review Focus 2).
   - read(out) GỘP với đầu vào đã có (phím): lấy giá trị có độ lớn lớn hơn cho gas / brake / steer, không xóa đầu vào phím (máy lai có cả phím lẫn cảm ứng).
   - Giữ yên ngón tay không phát sự kiện nên read báo activity() mỗi activityMs khi đang giữ gì đó; mỗi khung không cấp phát (D-018). */
import { CONFIG } from '../../config';
import type { DrInput } from './motion';

export interface DrTouchHandlers { look(dxPx: number, dyPx: number): void; activity(): void }

/* Độ lệch núm dx (px, phải +) trên cần gạt bán kính hành trình r → steer (−1..1, trái +): vùng chết rồi co giãn về ±1; dx < 0 (ngón sang trái) cho steer dương */
export function drSteerFromDx(dx: number, r: number): number {
  const k = r > 0 ? Math.max(-1, Math.min(1, dx / r)) : 0, a = Math.abs(k), D = CONFIG.drive.touch.dead;
  if (a <= D) return 0;
  return -Math.sign(k) * (a - D) / (1 - D);
}

export function drTouchBind(root: HTMLElement, h: DrTouchHandlers): { read(out: DrInput): void; reset(): void } {
  const pad = root.querySelector<HTMLElement>('#drSteer'), knob = root.querySelector<HTMLElement>('#drKnob');
  const gas = root.querySelector<HTMLElement>('#drGas'), brake = root.querySelector<HTMLElement>('#drBrake'), look = root.querySelector<HTMLElement>('#drLook');
  const T = CONFIG.drive.touch;
  const sp = (k: string, v: number) => root.style.setProperty(k, v + 'px');   // kích thước các nút lấy từ CONFIG
  sp('--dr-pad-w', T.padW); sp('--dr-pad-h', T.padH); sp('--dr-knob', T.knob);
  sp('--dr-gas-w', T.gasW); sp('--dr-gas-h', T.gasH); sp('--dr-brake-w', T.brakeW); sp('--dr-brake-h', T.brakeH);
  let padId = -1, cx = 0, dx = 0, r = (T.padW - T.knob) / 2;          // cần gạt: con trỏ, tâm x (px màn hình, chốt lúc chạm), độ lệch núm, hành trình núm
  let padW = 0, padH = 1, lastAct = 0;                                  // cỡ khung nhìn lúc chạm cần gạt hoặc bàn đạp, lần báo "còn đó" gần nhất (ms)
  let gasId = -1, brakeId = -1, lookId = -1, lx = 0, ly = 0;          // hai bàn đạp, vuốt camera (vị trí trước)
  const own = (el: HTMLElement, e: PointerEvent) => { try { el.setPointerCapture(e.pointerId); } catch { /* con trỏ không còn hoạt động (sự kiện giả) */ } };
  const lit = (el: HTMLElement | null, on: boolean) => { if (el) el.classList.toggle('on', on); };
  const knobTo = (x: number) => { if (knob) knob.style.transform = x === 0 ? '' : `translateX(${x}px)`; };
  const reset = () => { padId = -1; gasId = -1; brakeId = -1; lookId = -1; dx = 0; knobTo(0); lit(gas, false); lit(brake, false); };

  if (pad) {
    pad.addEventListener('pointerdown', (e) => {
      if (padId >= 0) return;
      e.preventDefault();
      const b = pad.getBoundingClientRect();
      cx = b.left + b.width / 2; r = Math.max(1, (b.width - (knob ? knob.offsetWidth || T.knob : T.knob)) / 2);
      padId = e.pointerId; padW = window.innerWidth; padH = window.innerHeight; lastAct = performance.now(); own(pad, e); h.activity();
      pad.dispatchEvent(new PointerEvent('pointermove', { pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY }));   // núm theo ngón ngay lúc chạm
    });
    pad.addEventListener('pointermove', (e) => {
      if (e.pointerId !== padId) return;
      dx = Math.max(-r, Math.min(r, e.clientX - cx));   // chỉ thành phần ngang; núm không ra khỏi hành trình
      knobTo(dx); h.activity();
    });
    const padEnd = (e: PointerEvent) => { if (e.pointerId === padId) { padId = -1; dx = 0; knobTo(0); } };
    pad.addEventListener('pointerup', padEnd);
    pad.addEventListener('pointercancel', padEnd);
    pad.addEventListener('lostpointercapture', padEnd);
  }

  /* Bàn đạp: giữ là 1, nhả là 0 */
  const pedal = (el: HTMLElement | null, get: () => number, set: (v: number) => void) => {
    if (!el) return;
    el.addEventListener('pointerdown', (e) => {
      if (get() >= 0) return;
      e.preventDefault();
      set(e.pointerId); padW = window.innerWidth; padH = window.innerHeight; lastAct = performance.now(); own(el, e); lit(el, true); h.activity();
    });
    const end = (e: PointerEvent) => { if (e.pointerId === get()) { set(-1); lit(el, false); } };
    el.addEventListener('pointerup', end);
    el.addEventListener('pointercancel', end);
    el.addEventListener('lostpointercapture', end);
  };
  pedal(gas, () => gasId, (v) => { gasId = v; });
  pedal(brake, () => brakeId, (v) => { brakeId = v; });

  if (look) {
    look.addEventListener('pointerdown', (e) => {
      if (lookId >= 0) return;
      e.preventDefault();
      lookId = e.pointerId; lx = e.clientX; ly = e.clientY; own(look, e); h.activity();
    });
    look.addEventListener('pointermove', (e) => {
      if (e.pointerId !== lookId) return;
      h.look(e.clientX - lx, e.clientY - ly); h.activity();
      lx = e.clientX; ly = e.clientY;
    });
    const lookEnd = (e: PointerEvent) => { if (e.pointerId === lookId) lookId = -1; };
    look.addEventListener('pointerup', lookEnd);
    look.addEventListener('pointercancel', lookEnd);
    look.addEventListener('lostpointercapture', lookEnd);
  }

  root.addEventListener('contextmenu', (e) => e.preventDefault());   // giữ lâu không bật menu ngữ cảnh
  window.addEventListener('blur', reset);
  document.addEventListener('visibilitychange', () => { if (document.hidden) reset(); });
  window.addEventListener('orientationchange', reset);
  /* Thanh địa chỉ điện thoại co giãn làm đổi innerHeight nhẹ: chỉ thả khi bề rộng đổi hoặc bề cao đổi quá resizeKeep (cùng ngưỡng với đi dạo) */
  window.addEventListener('resize', () => {
    if (padId < 0 && gasId < 0 && brakeId < 0) return;
    if (window.innerWidth !== padW || Math.abs(window.innerHeight - padH) > padH * CONFIG.stroll.stick.resizeKeep) reset();
  });

  return {
    read(out: DrInput): void {
      const held = padId >= 0 || gasId >= 0 || brakeId >= 0;
      if (!held) return;
      if (gasId >= 0) out.gas = 1;
      if (brakeId >= 0) out.brake = 1;
      if (padId >= 0) { const s = drSteerFromDx(dx, r); if (Math.abs(s) > Math.abs(out.steer)) out.steer = s; }
      const now = performance.now();   // giữ yên không phát sự kiện: báo "còn đó" thưa
      if (now - lastAct >= T.activityMs) { lastAct = now; h.activity(); }
    },
    reset
  };
}

