import { bentBox } from 'D:/2026 - Tuan/danang-vite/src/common/geometry';
import { HR, hrRoadY } from 'D:/2026 - Tuan/danang-vite/src/bridges/han-tunnel/profile';
import { drCutAlongX, drOnNewRoad } from 'D:/2026 - Tuan/danang-vite/src/environment/driveRoadGeo';
import { CONFIG } from 'D:/2026 - Tuan/danang-vite/src/config';
import * as fs from 'node:fs';
const tri = (g: any) => (g.index ? g.index.count : g.attributes.position.count) / 3;
const src = fs.readFileSync('D:/2026 - Tuan/danang-vite/src/bridges/han-tunnel/outdoor.ts', 'utf8');
const m = /const c = ([^;,]+)[;,]/.exec(src.slice(src.indexOf('function hrBuildSurface')));
console.log('c expr:', m && m[1]);
for (const c of [HR.rampHalf, (HR as any).coverHalf, 745, 760, 780].filter((v) => typeof v === 'number')) {
  let before = 0, after = 0;
  for (const [x0, x1] of [[-1900, -c], [c, 1480]]) {
    const len = x1 - x0, xc = (x0 + x1) / 2, segs = Math.ceil(len / 8);
    before += tri(bentBox(len, 0.3, HR.tubeNear * 2, xc, 0.15, 0, segs, hrRoadY));
    for (const z of [-1, 1]) before += tri(bentBox(len, 0.2, 3, xc, 0.1, z * (HR.tubeFar + 1.5), segs, hrRoadY));
    for (const g of drCutAlongX(x0, x1, HR.z, HR.tubeNear, segs, (l, xcc, n) => bentBox(l, 0.3, HR.tubeNear * 2, xcc, 0.15, 0, n, hrRoadY))) after += tri(g);
    for (const z of [-1, 1]) for (const g of drCutAlongX(x0, x1, HR.z + z * (HR.tubeFar + 1.5), 1.5, segs, (l, xcc, n) => bentBox(l, 0.2, 3, xcc, 0.1, z * (HR.tubeFar + 1.5), n, hrRoadY))) after += tri(g);
  }
  console.log('c', c, 'before', before, 'after', after, 'delta', after - before);
}
EOF
